int read_gab2_subtitle_packet(AVFormatContext *s, AVStream *st, AVPacket *pkt) {
    uint8_t *buf;
    AVIOContext *bc = NULL;
    int ret = 0;
    Gab2SubtitleContext *sub_ctx;

    if (pkt->size < 16)
        goto fail;

    if (memcmp(pkt->data, "GAB2", 4) != 0)
        goto fail;

    buf = av_malloc(pkt->size);
    if (!buf)
        goto fail;

    bc = avio_alloc_context(buf, pkt->size, 0, NULL, NULL, NULL, NULL);
    if (!bc)
        goto fail;

    avio_read(bc, NULL, pkt->size);

    sub_ctx = av_mallocz(sizeof(Gab2SubtitleContext));
    if (!sub_ctx)
        goto fail;

    st->codecpar->codec_tag = AV_RL32("GAB2");
    st->codecpar->format = AV_SAMPLE_FMT_NONE;
    st->codecpar->codec_type = AVMEDIA_TYPE_SUBTITLE;
    st->codecpar->extradata = av_malloc(pkt->size);
    if (!st->codecpar->extradata)
        goto fail;

    memcpy(st->codecpar->extradata, pkt->data, pkt->size);
    st->codecpar->extradata_size = pkt->size;

    st->pts_rect = 1;
    st->time_base = (AVRational){1, 1000};

    ret = 1;
    goto end;

fail:
    av_freep(&sub_ctx);
    av_freep(&st->codecpar->extradata);
    av_freep(&buf);
    avio_context_free(&bc);
    ret = 0;

end:
    return ret;
}

int read_gab2_subtitle_packet(AVFormatContext *s, AVStream *st, AVPacket *pkt) {
    if (!pkt || pkt->size < 4) {
        return 0;
    }

    // Check for GAB2 identifier
    if (memcmp(pkt->data, "GAB2", 4) != 0) {
        return 0;
    }

    AVIOContext *avio_ctx = avio_alloc_context(pkt->data + 4, pkt->size - 4, 0, NULL, NULL, NULL, NULL);
    if (!avio_ctx) {
        return 0;
    }

    // Extract metadata and validate subtitle format
    int subtitle_format = avio_r8(avio_ctx);
    if (subtitle_format != 1) {
        avio_context_free(&avio_ctx);
        return 0;
    }

    // Allocate new subtitle context
    GAB2SubtitleContext *sub_ctx = av_mallocz(sizeof(GAB2SubtitleContext));
    if (!sub_ctx) {
        avio_context_free(&avio_ctx);
        return 0;
    }

    // Copy parameters and set up subtitle stream context
    sub_ctx->packet_size = pkt->size;
    sub_ctx->presentation_timestamp = pkt->pts;

    st->codecpar->codec_type = AVMEDIA_TYPE_SUBTITLE;
    st->codecpar->codec_id = AV_CODEC_ID_GAB2;

    st->priv_data = sub_ctx;

    avio_context_free(&avio_ctx);
    return 1;
}

int read_gab2_subtitle_packet(AVFormatContext *s, AVStream *st, AVPacket *pkt) {
    if (!pkt || pkt->size < 4)
        return 0;

    if (memcmp(pkt->data, "GAB2", 4) != 0)
        return 0;

    AVIOContext *bc = NULL;
    int ret = 0;

    bc = avio_alloc_context(pkt->data + 4, pkt->size - 4, 0, NULL, NULL, NULL, NULL);
    if (!bc) {
        ret = 0;
        goto fail;
    }

    if (!st->codecpar->codec_type)
        st->codecpar->codec_type = AVMEDIA_TYPE_SUBTITLE;

    if (!st->codecpar->codec_id)
        st->codecpar->codec_id = AV_CODEC_ID_GAB2;

    if (!st->codecpar->format)
        st->codecpar->format = AV_PIX_FMT_NONE;

    st->codecpar->extradata = av_malloc(pkt->size - 4 + FF_INPUT_BUFFER_PADDING_SIZE);
    if (!st->codecpar->extradata) {
        ret = 0;
        goto fail;
    }

    st->codecpar->extradata_size = pkt->size - 4;
    memcpy(st->codecpar->extradata, bc->buffer, pkt->size - 4);

    avio_skip(bc, pkt->size - 4);
    av_free(bc);

    st->pts = pkt->pts;
    st->time_base = st->codecpar->time_base;

    return 1;

fail:
    if (bc)
        av_free(bc);
    return ret;
}

int read_gab2_subtitle_packet(AVFormatContext *s, AVStream *st, AVPacket *pkt) {
    if (!pkt || pkt->size < 4) {
        return 0;
    }

    if (AV_RB32(pkt->data) != MKTAG('G', 'A', 'B', '2')) {
        return 0;
    }

    AVIOContext *ioc = avio_alloc_context(pkt->data + 4, pkt->size - 4, 0, NULL,
        NULL, NULL, NULL);
    if (!ioc) {
        return 0;
    }

    int format = avio_r8(ioc);
    int width = avio_rl16(ioc);
    int height = avio_rl16(ioc);

    AVCodecParameters *par = avcodec_parameters_alloc();
    if (!par) {
        avio_free(ioc);
        return 0;
    }

    par->codec_type = AVMEDIA_TYPE_SUBTITLE;
    par->format = format;
    par->width = width;
    par->height = height;

    if (avcodec_parameters_to_context(st->codec, par) < 0) {
        avio_free(ioc);
        avcodec_parameters_free(&par);
        return 0;
    }

    st->time_base = (AVRational){1, 1000};
    st->start_time = av_rescale_q(avio_rl32(ioc), (AVRational){1, 1000}, st->time_base);
    st->duration = av_rescale_q(avio_rl32(ioc), (AVRational){1, 1000}, st->time_base);

    avio_free(ioc);
    avcodec_parameters_free(&par);

    return 1;
}

int read_gab2_subtitle_packet(AVFormatContext *s, AVStream *st, AVPacket *pkt) {
    if (!pkt || pkt->size < 4) {
        return 0;
    }

    if (AV_RB32(pkt->data) != MKTAG('G', 'A', 'B', '2')) {
        return 0;
    }

    AVIOContext *bc = avio_alloc_context(pkt->data, pkt->size, 0, NULL, NULL, NULL, NULL);
    if (!bc) {
        return 0;
    }

    AVRational time_base = { 1, 100 };
    AVCodecParameters *par = avcodec_parameters_alloc();
    if (!par) {
        avio_context_free(&bc);
        return 0;
    }

    par->codec_type = AVMEDIA_TYPE_SUBTITLE;
    par->format = AV_CODEC_ID_GAB2;

    if (avcodec_parameters_copy(st->codecpar, par) < 0) {
        avio_context_free(&bc);
        avcodec_parameters_free(&par);
        return 0;
    }

    st->time_base = time_base;
    avio_context_free(&bc);
    avcodec_parameters_free(&par);

    return 1;
}
